// Generated by gstack /ship Step 7 coverage audit (pass 1).
// Value cards, one per test, are in the comment above each test.
import { afterAll, describe, expect, test } from "bun:test";
import { existsSync, mkdtempSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { Database } from "bun:sqlite";
import { openLease, reconcileLease, recordApproval, settleLease } from "../../src/runner/ledger/ledger.ts";
import { LocalLedger } from "../../src/runner/ledger/local.ts";
import { LedgerError, readItem, writeOnce, type LeaseFile } from "../../src/runner/ledger/record.ts";
import type { TokenUsage } from "../../src/types.ts";

const dirs: string[] = [];
afterAll(() => dirs.forEach((d) => rmSync(d, { recursive: true, force: true })));
const scratch = () => {
  const d = mkdtempSync(join(tmpdir(), "ledger-edges-"));
  dirs.push(d);
  return d;
};
const quote = { words: "Rec", by: "Garry Tan", source: "gate 1" };
const DOLLAR = 1_000_000;
const cell = { run_id: "run-a", arm: "after", task: "t1", model: "m", trial: 1, attempt: 1, meter_id: "m-1" };
const usage: TokenUsage = { input: 10, output: 5, reasoning: 0, cache_read: 0, cache_write: 0 };
const leaseFile: LeaseFile = { schema: 1, kind: "lease", item: "lanea", seq: 1, lease_id: "lanea.0001.aaaaaa", run_id: "r", machine_id: "m", reserved_micros: 1, expires_at: "2026-10-29T00:00:00.000Z", created_at: "2026-10-28T00:00:00.000Z" };

function funded(cap = 5 * DOLLAR) {
  const dir = scratch();
  const record = join(dir, "record");
  recordApproval(record, { action: "init", item: "lanea", cap_micros: cap, quotes: [quote] });
  return { dir, record, local: LocalLedger.open(join(dir, "a.sqlite")) };
}

function codeOf(fn: () => unknown): string {
  try {
    fn();
  } catch (error) {
    if (error instanceof LedgerError) return error.code;
    throw error;
  }
  return "ok";
}

describe("ledger edges", () => {
  // Value: protects=a settled lease cannot be reconciled to another figure; fails_when=reconcile ignores a prior settled close; why_new=ledger.test.ts covers reconciled-vs-settled only; seam=none; no_claim=none beyond protects
  test("reconciling a lease that was already settled is E_SETTLE_CONFLICT and the settled close stands", () => {
    const dir = scratch();
    const record = join(dir, "record");
    recordApproval(record, { action: "init", item: "lanea", cap_micros: 5 * DOLLAR, quotes: [quote] });
    const local = LocalLedger.open(join(dir, "a.sqlite"));
    const lease = openLease(record, local, { item: "lanea", run_id: "run-a", amount_micros: DOLLAR });
    settleLease(record, local, lease.lease_id);
    const exportFile = join(dir, "usage.csv");
    writeFileSync(exportFile, "cost\n0.5\n");
    const owner = { lease_id: lease.lease_id, spent_micros: 500_000, quotes: [quote], source: exportFile, now: new Date(Date.parse(lease.expires_at) + 1) };
    expect(codeOf(() => reconcileLease(record, owner))).toBe("E_SETTLE_CONFLICT");
    expect(readItem(record, "lanea").leases[0]!.close).toMatchObject({ how: "settled", spent_micros: 0 });
    expect(codeOf(() => reconcileLease(record, { ...owner, lease_id: "lanea.0009.abcdef" }))).toBe("E_LEASE_UNSETTLED");
    local.close();
  });

  // Value: protects=approval input guards (item name, positive integer cap); fails_when=a guard is removed so a bad name or zero cap is recorded; why_new=no test feeds a bad name or cap; seam=none; no_claim=CLI flag parsing
  test("an approval with a bad item name or a non-positive or fractional cap is E_USAGE and writes nothing", () => {
    const record = join(scratch(), "record");
    for (const a of [
      { item: "Lane A", cap_micros: DOLLAR },
      { item: "../x", cap_micros: DOLLAR },
      { item: "lanea", cap_micros: 0 },
      { item: "lanea", cap_micros: 1.5 },
    ]) expect(codeOf(() => recordApproval(record, { action: "init", quotes: [quote], ...a }))).toBe("E_USAGE");
    expect(existsSync(join(record, "items"))).toBe(false);
  });

  // Value: protects=a close naming a lease other than its slot's is an unreadable record; fails_when=the lease_id cross-check in readItem is dropped; why_new=record.test.ts covers torn files and gaps only; seam=none; no_claim=none beyond protects
  test("a close that names another lease is E_LEDGER_RECORD", () => {
    const record = scratch();
    const lease = { schema: 1 as const, kind: "lease" as const, item: "lanea", seq: 1, lease_id: "lanea.0001.aaaaaa", run_id: "r", machine_id: "m", reserved_micros: 1, expires_at: "2026-10-29T00:00:00.000Z", created_at: "2026-10-28T00:00:00.000Z" };
    writeOnce(record, lease);
    writeOnce(record, { schema: 1, kind: "close", item: "lanea", seq: 1, lease_id: "lanea.0001.bbbbbb", how: "settled", spent_micros: 0, unknown_micros: 0, unknown_calls: 0, usage: null, closed_at: "2026-10-28T01:00:00.000Z" });
    expect(codeOf(() => readItem(record, "lanea"))).toBe("E_LEDGER_RECORD");
  });

  // Value: protects=local ledger refuses unknown leases, fractional amounts and foreign files; fails_when=reserve admits a lease it never recorded or opens a non-ledger DB; why_new=no test covers these refusals; seam=none; no_claim=none beyond protects
  test("the local ledger refuses an unknown lease, a fractional amount and a file of another format", async () => {
    const dir = scratch();
    const local = LocalLedger.open(join(dir, "a.sqlite"));
    expect(await local.reserve({ idempotency_key: "k1", lease_id: "lanea.0001.aaaaaa", cell, max_micros: 1 })).toMatchObject({ ok: false, code: "E_LEDGER_MISSING" });
    expect(await local.reserve({ idempotency_key: "k2", lease_id: "lanea.0001.aaaaaa", cell, max_micros: 0.5 })).toMatchObject({ ok: false, code: "E_INTERNAL" });
    local.close();
    const foreign = join(dir, "other.sqlite");
    const db = new Database(foreign, { create: true });
    db.exec("CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL); INSERT INTO meta VALUES ('format', 'something-else/9');");
    db.close();
    expect(() => LocalLedger.open(foreign)).toThrow("not gstack-evals-ledger/1");
    const other = join(dir, "app.sqlite");
    const app = new Database(other, { create: true });
    app.exec("CREATE TABLE notes (body TEXT)");
    app.close();
    expect(() => LocalLedger.open(other)).toThrow("not gstack-evals-ledger/1");
    for (const file of [foreign, other]) {
      const check = new Database(file);
      expect((check.query("SELECT name FROM sqlite_master WHERE type = 'table' ORDER BY name").all() as { name: string }[]).map((t) => t.name)).toEqual(file === foreign ? ["meta"] : ["notes"]);
      check.close();
    }
  });

  // Value: protects=a path-like item or a slot past 9999 is refused before any read or write; fails_when=the item or slot guard in readItem or writeOnce is dropped; why_new=only recordApproval fed bad names; seam=none; no_claim=none beyond protects
  test("a path-like line item and a slot past 9999 are refused, and the real item stays readable", () => {
    const { record, local } = funded();
    expect(codeOf(() => openLease(record, local, { item: "x/../lanea", run_id: "run-a" }))).toBe("E_USAGE");
    expect(codeOf(() => writeOnce(record, { ...leaseFile, item: "x/../lanea" }))).toBe("E_USAGE");
    expect(codeOf(() => readItem(record, "../record"))).toBe("E_USAGE");
    expect(codeOf(() => writeOnce(record, { ...leaseFile, seq: 10_000 }))).toBe("E_LEDGER_RECORD");
    expect(readItem(record, "lanea")).toMatchObject({ leases: [], cap_micros: 5 * DOLLAR });
    local.close();
  });

  // Value: protects=settle refuses a fractional charge or malformed token counts and keeps only known counts; fails_when=a settle guard is dropped and a bad figure reaches the write-once close; why_new=only reserve's guard was tested; seam=none; no_claim=none beyond protects
  test("settle refuses a fractional charge and malformed token counts, keeps only known counts, and repeats an unknown settle", async () => {
    const { record, local } = funded();
    const lease = openLease(record, local, { item: "lanea", run_id: "run-a", amount_micros: DOLLAR });
    const request = { idempotency_key: "k1", lease_id: lease.lease_id, cell, max_micros: 500_000 };
    const r = await local.reserve(request);
    if (!r.ok) throw new Error(r.message);
    const id = r.reservation.reservation_id;
    expect(await local.settle(id, { kind: "spent", spent_micros: 0.5, usage })).toMatchObject({ ok: false, code: "E_INTERNAL" });
    expect(await local.settle(id, { kind: "spent", spent_micros: 1, usage: { input: 1, output: "2" } as unknown as TokenUsage })).toMatchObject({ ok: false, code: "E_INTERNAL" });
    expect(await local.reserve(request)).toMatchObject({ ok: true, reservation: { state: "reserved" } });
    expect(await local.settle(id, { kind: "spent", spent_micros: 1, usage: { ...usage, cost: 5 } as TokenUsage })).toMatchObject({ ok: true, reservation: { usage } });
    const u = await local.reserve({ ...request, idempotency_key: "k2" });
    if (!u.ok) throw new Error(u.message);
    await local.settle(u.reservation.reservation_id, { kind: "unknown" });
    expect(await local.settle(u.reservation.reservation_id, { kind: "unknown" })).toMatchObject({ ok: true, reservation: { state: "unknown" } });
    expect(settleLease(record, local, lease.lease_id)).toMatchObject({ spent_micros: 1, unknown_micros: 500_000, usage });
    local.close();
  });

  // Value: protects=settling a closed lease from a machine without it answers with the recorded close and writes nothing; fails_when=settleLease answers from the missing local row; why_new=the lost-machine test settles an open lease only; seam=none; no_claim=none beyond protects
  test("settling a closed lease on a machine without it returns the recorded close and leaves the record unchanged", () => {
    const { dir, record, local } = funded();
    const lease = openLease(record, local, { item: "lanea", run_id: "run-a", amount_micros: DOLLAR });
    const close = settleLease(record, local, lease.lease_id);
    const files = readdirSync(join(record, "items", "lanea"));
    const machineB = LocalLedger.open(join(dir, "b.sqlite"));
    expect(settleLease(record, machineB, lease.lease_id)).toEqual(close);
    expect(readdirSync(join(record, "items", "lanea"))).toEqual(files);
    local.close();
    machineB.close();
  });

  // Value: protects=a malformed lease amount, time to live or expiry is refused before it binds or fails open; fails_when=the amount, ttl or expires_at checks are dropped; why_new=no test fed these; seam=none; no_claim=none beyond protects
  test("a zero, negative or fractional amount is CAP_STOP, a bad time to live is E_USAGE, and a lease without a valid expiry is refused", () => {
    const { dir, record, local } = funded();
    for (const amount_micros of [0, -1, 1.5]) expect(codeOf(() => openLease(record, local, { item: "lanea", run_id: "run-a", amount_micros }))).toBe("CAP_STOP");
    for (const ttl_ms of [0, -5, 1.5]) expect(codeOf(() => openLease(record, local, { item: "lanea", run_id: "run-a", ttl_ms }))).toBe("E_USAGE");
    expect(readItem(record, "lanea").leases).toEqual([]);
    expect(codeOf(() => local.addLease({ ...leaseFile, expires_at: "soon" }))).toBe("E_USAGE");
    const bad = join(dir, "bad-record");
    writeOnce(bad, { ...leaseFile, expires_at: "soon" });
    expect(codeOf(() => readItem(bad, "lanea"))).toBe("E_LEDGER_RECORD");
    local.close();
  });

  // Value: protects=a reconcile retried with another spelling of the same export path is the same reconcile; fails_when=idempotency compares the raw path text; why_new=the reconcile test retries with the identical path; seam=none; no_claim=none beyond protects
  test("a reconcile retried with another spelling of the same export path returns the recorded close", () => {
    const { dir, record } = funded();
    const lease = openLease(record, null, { item: "lanea", run_id: "run-a", amount_micros: DOLLAR, ttl_ms: 1, now: new Date(Date.now() - 60_000) });
    writeFileSync(join(dir, "usage.csv"), "cost\n0.4\n");
    const owner = { lease_id: lease.lease_id, spent_micros: 400_000, quotes: [quote], source: join(dir, "usage.csv") };
    const close = reconcileLease(record, owner);
    expect(reconcileLease(record, { ...owner, source: dir + "/./usage.csv" })).toEqual(close);
  });
});
